-- PT103-S3-Q7. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT103-S3-Q7$batch11$ AND q.stimulus=$batch11$Lack of exercise produces the same or similar bodily effects as aging. In fact, the physical changes that accompany aging can often be slowed down by appropriate exercise. No drug, however, holds any promise for slowing down the changes associated with aging. Therefore,  _______ .$batch11$ AND q.prompt=$batch11$Which one of the following provides a logical completion to the passage above?$batch11$ AND q.correct_choice=$batch11$E$batch11$) THEN RAISE EXCEPTION 'Question changed: PT103-S3-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT103-S3-Q7$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S3-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT103-S3-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Lack of exercise causes effects like aging. Appropriate exercise can often slow the changes of aging. No drug holds any promise of slowing them.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$The blank follows "Therefore," so it has to be what the facts support. Exercise often works. Drugs hold no promise. So if you want to slow aging, exercise is the better bet.$batch11$), (2, $batch11$Goal$batch11$, $batch11$To slow aging, exercise is more practical than drugs.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT103-S3-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Drugs have no promise of slowing aging. That doesn't mean they speed it up the way lack of exercise does.$batch11$), ($batch11$B$batch11$, $batch11$Nothing says people who skip exercise need drugs. Drugs are actually described as useless for aging.$batch11$), ($batch11$C$batch11$, $batch11$Exercise can often slow the changes. Prevent is much stronger than slow.$batch11$), ($batch11$D$batch11$, $batch11$Age at which exercise starts never comes up.$batch11$), ($batch11$E$batch11$, $batch11$Exercise often slows aging. Drugs hold no promise. Exercise is the more practical choice.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT103-S3-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
